const myPendingClaims=d=>Object.entries(d.pendingClaims||{}).filter(([id,c])=>Number(c.team)===Number(d.members?.[uid]?.team));
function studentInstruction(d,g){if(host)return '👩‍🏫 선생님 · '+(g.phase==='finished'?'최종 결과를 확인해 주세요.':'학생들의 활동과 문제 승인을 확인해 주세요.');const current=names[g.team]||'고구려',mine=isTeamMember(d,g);if(g.phase==='finished')return '🏆 게임 종료! 최종 순위를 확인해요.';if(g.phase==='order')return '🎲 시작 순서 결정 · '+names[g.orderTurn||0]+' 팀 첫 입장 학생 '+(d.members?.[firstPlayer(d,g.orderTurn||0)]?.nickname||'대기 중')+(orderCanRoll(d,g,uid)?' · 내 주사위 버튼이 활성화됐어요!':'만 주사위를 굴려요.');if(!mine)return '지금은 '+current+' 차례예요. '+(myPendingClaims(d).length?'우리 팀은 문제를 계속 출제할 수 있어요.':'우리 차례를 기다려요.');if(g.phase==='roll')return '지금은 '+current+' 차례예요. '+(player(d,g)===uid?'내가 주사위를 굴려요!':'우리 팀 친구가 주사위를 굴려요.');if(g.phase==='wait')return '⏳ 이 거점은 문제 출제 중입니다. 출제 완료 후 새 문제를 풀어요.';if(g.phase==='quiz')return '지금은 '+current+' 차례예요. 문제를 풀어 거점을 차지해요!';if(g.phase==='author')return '📝 출제중 버튼을 누르면 다음 나라가 주사위를 굴립니다. 문제는 계속 작성하세요!';return '지금은 '+current+' 차례예요. 다음 차례를 기다려요.';}
function drawFinal(g){const area=$('finalResults');if(g.phase!=='finished'){area.classList.add('hidden');return}area.classList.remove('hidden');const rows=names.map((name,team)=>({name,team,...scoreBreakdown(g,team)})).sort((a,b)=>b.total-a.total||a.team-b.team);const winners=rows.filter(x=>x.total===rows[0].total).map(x=>x.name);$('winnerTitle').textContent='🏆 '+winners.join(' · ')+' '+(winners.length>1?'공동 우승!':'우승!');$('finalTable').innerHTML='<p class="muted">총점 = 거점 국력 + 라운딩 횟수(1회 1점) + 현재 점령 거점 수(1곳 1점) + 카드 누적 점수<br>총점이 같으면 공동 순위입니다.</p>'+rows.map(x=>'<div class="final-row" style="background:'+colors[x.team]+'"><span>'+(1+rows.filter(other=>other.total>x.total).length)+'위 · '+x.name+'</span><strong>총점 '+x.total+'점</strong><div style="width:100%;font-size:16px;line-height:1.7;font-weight:600">🏯 거점 국력: '+x.territory+'점 (꾸미기 +'+x.decorations+' 포함)<br>🏁 라운딩: '+x.laps+'회 → '+x.laps+'점<br>🚩 점령 거점: '+x.count+'곳 → '+x.count+'점<br>📜 기회·사건 카드: '+(x.cards>0?'+':'')+x.cards+'점<br><b>'+x.territory+' + '+x.laps+' + '+x.count+' + ('+x.cards+') = '+x.total+'점</b></div></div>').join('');}
const startOrder=(rolls)=>Object.keys(rolls||{}).map(Number).sort((a,b)=>rolls[b]-rolls[a]);
const facing=i=>i<9?'right':i<17?'down':i<25?'left':'up';
const safeImage=url=>{if(typeof url!=='string')return '';if(/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(url)&&url.length<=90000)return url;try{const u=new URL(url);return u.protocol==='https:'&&url.length<=500?u.href:''}catch{return ''}};
async function compressPhoto(file){if(!file)return '';if(!file.type.startsWith('image/'))throw Error('이미지 파일을 선택해 주세요.');const bitmap=await createImageBitmap(file);try{const canvas=document.createElement('canvas'),max=400,scale=Math.min(1,max/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);for(const quality of [.7,.5,.35,.2]){const data=canvas.toDataURL('image/jpeg',quality);if(data.length<=90000)return data}throw Error('이미지 용량이 큽니다. 다른 사진을 선택하세요.')}finally{bitmap.close()}}
function refreshTopicSelectors(){if(!roomData)return;const owned=roomData.game?.owners||[];const team=Number(roomData.members?.[uid]?.team??-1);const select=$('landmarkTopic'),prev=select.value;select.innerHTML='';for(let i=0;i<24;i++){if(Number(owned[i])!==team&&!host)continue;const op=document.createElement('option');op.value=i;op.textContent='거점 '+(i+1)+(roomData.landmarks?.[i]?.name?' · '+roomData.landmarks[i].name:'');select.appendChild(op)}if([...select.options].some(o=>o.value===prev))select.value=prev;$('landmarkSubmit').disabled=!select.options.length;$('landmarkStatus').textContent=select.options.length?'점령한 거점을 선택해 이름과 이미지를 등록하세요.':'점령한 거점이 생기면 이곳에서 꾸밀 수 있습니다.';}
function studentPieces(d,g){return names.flatMap((name,team)=>roster(d,team).map(([id,m],index)=>{const token=g.studentTokens?.[id],position=token&&Number(token.team)===team?Number(token.position):g.studentTokens?0:Number(g.positions?.[team]||0);return {id,team,number:index+1,nickname:m.nickname,position};}));}
function piecesAt(d,g,i){return studentPieces(d,g).filter(p=>p.position===i);}
function pieceHTML(p,i,active){return '<span class="horse student-horse horse-'+p.team+' face-'+facing(i)+(p.id===active?' active-horse':'')+'" title="'+clean(names[p.team]+' '+p.number+'번 · '+p.nickname)+'"><span aria-hidden="true">🐎</span><small>'+p.number+'</small></span>';}
let audioCtx=null,soundEnabled=localStorage.getItem('historySound')!=='off',effectState=null,effectTimers=[];
function initEffects(){if($('soundToggle'))return;const style=document.createElement('style');style.textContent='.arrival-fx{animation:arrivalPulse 1s ease-out 3!important;z-index:5}.capture-fx{animation:captureGlow .8s ease-in-out 3!important;z-index:5}@keyframes arrivalPulse{50%{outline:5px solid #ffb400;box-shadow:0 0 28px #ffb400;transform:scale(1.06)}}@keyframes captureGlow{50%{outline:5px solid #29b874;box-shadow:0 0 32px #29b874}}#gameFx{position:fixed;inset:0;pointer-events:none;z-index:9998;overflow:hidden}.fx-toast{position:absolute;left:50%;top:30%;transform:translateX(-50%);background:#fff9e9;color:#163451;border:4px solid #e1a11b;border-radius:22px;padding:18px 30px;font-size:clamp(25px,4vw,52px);font-weight:950;text-align:center;max-width:90vw;box-shadow:0 8px 35px #0004;animation:toastPop 2.4s ease both}.fx-particle{position:absolute;top:35%;left:50%;font-size:27px;animation:confettiFly 1.8s ease-out forwards;--dx:0px;--dy:200px}@keyframes confettiFly{to{transform:translate(var(--dx),var(--dy)) rotate(340deg);opacity:0}}@keyframes toastPop{0%{opacity:0;scale:.7}12%,80%{opacity:1;scale:1}100%{opacity:0}}@media(prefers-reduced-motion:reduce){.arrival-fx,.capture-fx,.fx-toast,.fx-particle{animation:none!important}.fx-particle{display:none}}';document.head.appendChild(style);const layer=document.createElement('div');layer.id='gameFx';layer.setAttribute('aria-hidden','true');document.body.appendChild(layer);const b=document.createElement('button');b.id='soundToggle';b.type='button';b.style.marginTop='10px';const refresh=()=>{b.textContent=soundEnabled?'🔊 효과음 켜짐':'🔇 효과음 꺼짐';b.setAttribute('aria-pressed',String(soundEnabled))};refresh();b.onclick=()=>{soundEnabled=!soundEnabled;localStorage.setItem('historySound',soundEnabled?'on':'off');refresh();if(soundEnabled){unlockAudio();playSound('arrival')}};document.querySelector('header').appendChild(b);document.addEventListener('pointerdown',unlockAudio,{passive:true});document.addEventListener('keydown',unlockAudio);}
function unlockAudio(){if(!soundEnabled)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;if(!audioCtx)audioCtx=new AC();if(audioCtx.state==='suspended')audioCtx.resume().catch(()=>{});}catch{}}
function playSound(kind){if(!soundEnabled||!audioCtx||audioCtx.state!=='running')return;const notes={roll:[[240,.06],[330,.06],[260,.06],[420,.08],[520,.1]],arrival:[[523,.12],[659,.16]],correct:[[523,.12],[659,.12],[784,.12],[1047,.3]],wrong:[[330,.18],[277,.18],[220,.3]],capture:[[523,.1],[659,.1],[784,.1],[1047,.25]],card:[[392,.14],[523,.14],[659,.22]]}[kind]||[];let time=audioCtx.currentTime;try{for(const [freq,duration] of notes){const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=kind==='wrong'?'triangle':'sine';osc.frequency.value=freq;gain.gain.setValueAtTime(0,time);gain.gain.linearRampToValueAtTime(.075,time+.015);gain.gain.exponentialRampToValueAtTime(.001,time+duration);osc.connect(gain);gain.connect(audioCtx.destination);osc.start(time);osc.stop(time+duration+.02);time+=duration}}catch{}}
function celebrate(text,success=false){const layer=$('gameFx');if(!layer)return;const toast=document.createElement('div');toast.className='fx-toast';toast.textContent=text;layer.appendChild(toast);if(success){for(let i=0;i<20;i++){const p=document.createElement('span');p.className='fx-particle';p.textContent=['✨','⭐','🎉'][i%3];p.style.setProperty('--dx',(Math.random()*600-300)+'px');p.style.setProperty('--dy',(Math.random()*500-180)+'px');layer.appendChild(p);setTimeout(()=>p.remove(),2000)}}setTimeout(()=>toast.remove(),2500);}
function flashTile(position,kind){document.querySelectorAll('.tile')[position]?.classList.add(kind);}
function updateEffects(d,g){initEffects();const current={room,roll:Number(g.rollStartedAt||0),turn:g.turnId,phase:g.phase,owners:[...(g.owners||[])],message:g.message||''};const old=effectState;effectState=current;if(!old||old.room!==room)return;if(current.roll&&current.roll!==old.roll){playSound('roll');const at=g.positions?.[g.team],turn=g.turnId;effectTimers.push(setTimeout(()=>{if(roomData?.game?.turnId!==turn)return;playSound(g.lastCard?'card':'arrival');flashTile(at,'arrival-fx');celebrate(g.lastCard?'📜 '+g.lastCard.title:'📍 '+names[g.team]+' 도착!')},Math.max(0,current.roll+3500-Date.now())))}
const captures=current.owners.map((v,i)=>Number(v)>=0&&Number(v)!==Number(old.owners[i])?i:-1).filter(i=>i>=0);const failed=current.phase==='next'&&current.message!==old.message&&/거점 획득 (실패|불가)/.test(current.message);if(captures.length){playSound('capture');celebrate('🏯 거점 획득!',true);for(const id of captures){flashTile(spaces.findIndex(s=>s.kind==='property'&&s.id===id),'capture-fx')}}else if(failed){playSound('wrong');celebrate('💤 거점 획득 실패 · 다음 차례 쉬기')}else if(old.phase==='wait'&&current.phase==='quiz'){playSound('arrival');celebrate('❓ 출제 완료! 문제를 풀어 주세요.')}}
function showLandmark(id){const d=roomData,g=d?.game;if(!g||!decorationPoint(g,id,d.landmarks))return;const dec=d.landmarks[id],image=safeImage(dec.imageUrl||'');let dialog=$('landmarkDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='landmarkDialog';dialog.style.cssText='border:0;border-radius:18px;padding:22px;max-width:min(92vw,560px);width:100%;text-align:center';document.body.appendChild(dialog)}dialog.innerHTML='<h2>'+clean(dec.name)+'</h2><p>'+clean(names[Number(g.owners[id])])+' · 거점 '+(Number(id)+1)+'</p>'+(image?'<img src="'+clean(image)+'" alt="'+clean(dec.name)+'" style="width:100%;max-height:55vh;object-fit:contain;border-radius:12px">':'<p style="font-size:70px">🏯</p>')+'<p style="font-size:22px;font-weight:900">거점 국력 '+(TERRITORY_POINTS[id]+1)+'점<br><small>기본 '+TERRITORY_POINTS[id]+' + 꾸미기 1</small></p><button type="button">닫기</button>';dialog.querySelector('button').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal();}
