async function doRoll(fromRequest){const d=roomData,g=d?.game;if(!d||!g||g.phase==='finished')return;if(!host){if(!(g.phase==='roll'&&player(d,g)===uid||g.phase==='order'&&orderCanRoll(d,g,uid)))return;try{await set(ref(db,'rooms/'+room+'/rollRequests/'+uid),{turnId:g.turnId,team:Number(d.members?.[uid]?.team),requestedAt:Date.now()});notify('🎲 주사위 요청을 보냈습니다. 교사 화면에서 처리 중입니다.')}catch(e){alert('주사위 요청 오류: '+e.message)}return}if(g.phase==='order'){if(!host&&!orderCanRoll(d,g,uid))return;const pair=twoDice(),value=pair[0]+pair[1],rolls={...(g.orderRolls||{}),[g.orderTurn]:value};if(g.orderTurn<3){await update(ref(db,'rooms/'+room+'/game'),{orderRolls:rolls,orderTurn:g.orderTurn+1,lastRoll:value,lastDice:pair,rollStartedAt:Date.now(),message:names[g.orderTurn]+' 팀 '+value+'! 다음 나라가 굴려 주세요.'});return}let order=startOrder(rolls),tie=order.some((x,i)=>i>0&&rolls[x]===rolls[order[i-1]]);if(tie){await update(ref(db,'rooms/'+room+'/game'),{orderRolls:{},orderTurn:0,lastRoll:value,lastDice:pair,rollStartedAt:Date.now(),message:'같은 숫자가 나왔습니다. 공정하게 다시 굴려 주세요.'});return}await update(ref(db,'rooms/'+room+'/game'),{order,team:order[0],orderTurn:4,phase:'roll',lastRoll:value,lastDice:pair,rollStartedAt:Date.now(),message:'시작 순서: '+order.map(t=>names[t]).join(' → ')});return}
if(g.phase!=='roll'||!canAct(d,g))return;const mover=player(d,g),pieces=studentPieces(d,g);if(!mover)return notify('이 나라에 입장한 학생이 없습니다. 교사가 다음 팀으로 넘겨 주세요.');const studentTokens={...(g.studentTokens||{})};for(const p of pieces)studentTokens[p.id]={team:p.team,position:p.position};const pair=twoDice(),steps=pair[0]+pair[1],bonusRoll=pair[0]===pair[1],positions=[...g.positions],old=studentTokens[mover].position,absolute=old+steps,next=absolute%spaces.length,laps=[...(g.laps||[0,0,0,0])];if(absolute>=spaces.length)laps[g.team]++;positions[g.team]=next;studentTokens[mover]={team:g.team,position:next};const sp=spaces[next];let lastCard=null;const cardPoints={...(g.cardPoints||{})};if(HISTORY_CARDS[sp.kind]){const deck=HISTORY_CARDS[sp.kind],card=deck[Math.floor(Math.random()*deck.length)];lastCard={kind:sp.kind,title:card[0],text:card[1],points:card[2],team:g.team};cardPoints[g.team]=Number(cardPoints[g.team]||0)+card[2]}const target=sp.kind==='property'?sp.id:null,owner=target===null?-1:Number(g.owners?.[target]??-1),claim=target===null?null:d.pendingClaims?.[target],phase=claim?(Number(claim.team)===Number(g.team)?'author':'wait'):target===null||owner===g.team?'next':owner<0?'author':'quiz',turnId=(g.turnId||0)+1;if(target!==null&&owner<0&&!pendingClaim(d,target)){await set(ref(db,'rooms/'+room+'/pendingClaims/'+target),{topic:target,team:g.team,turnId,createdAt:Date.now()})}await update(ref(db,'rooms/'+room+'/game'),{positions,studentTokens,laps,turnId,lastCard,cardPoints,lastRoll:steps,lastDice:pair,rollStartedAt:Date.now(),bonusRoll,questionId:target,phase,message:phase==='wait'?'⏳ '+names[Number(claim.team)]+' 팀이 거점 '+(target+1)+' 문제를 출제 중입니다. 완료되면 새 문제를 풀 수 있습니다.':lastCard?'📜 '+names[g.team]+' · '+lastCard.title+' · 국력 '+(lastCard.points>0?'+':'')+lastCard.points+'점':target!==null&&owner<0?'📝 거점 '+(target+1)+'에 도착! 출제중 버튼을 누르면 다음 나라 차례가 시작됩니다.':phase==='quiz'?'상대 나라 영토입니다. 문제를 풀어 재점령에 도전하세요.':names[g.team]+' 팀 '+steps+'칸 이동! 다음 차례로 넘어갑니다.'});}
