async function failQuiz(){if(!host||roomData?.game?.phase!=='quiz')return;if(!confirm('거점을 획득하지 못하고 다음 자기 차례를 한 번 쉬게 할까요?'))return;const turnId=roomData.game.turnId;await runTransaction(ref(db,'rooms/'+room+'/game'),g=>{if(!g||g.phase!=='quiz'||g.turnId!==turnId)return;const skipTurns={...(g.skipTurns||{})};skipTurns[g.team]=Number(skipTurns[g.team]||0)+1;return {...g,skipTurns,bonusRoll:false,phase:'next',message:'⏳ '+names[g.team]+' 팀 문제 풀이 실패 · 거점 획득 불가 · 다음 자기 차례 1회 쉬기.'}},{applyLocally:false});}
