async function submitAnswer(choice){const g=roomData?.game;if(answerSubmitting||!g||g.phase!=='quiz'||(!host&&!isTeamMember(roomData,g)))return;const passed=choice===null;if(!passed&&(!Number.isInteger(choice)||choice<0||choice>3))return;const previous=roomData.attempts?.[uid];if(previous?.turnId===g.turnId)return;answerSubmitting=true;try{await set(ref(db,`rooms/${room}/attempts/${uid}`),{turnId:g.turnId,choice:passed?0:choice,passed,team:g.team,submittedAt:Date.now(),nickname:roomData.members?.[uid]?.nickname||'참가자'});notify(passed?'🤷 모름·패스로 제출했습니다. 다른 팀원은 계속 풀 수 있어요.':'답안을 제출했습니다. 결과를 기다립니다.')}catch(e){alert('제출 실패: '+e.message)}finally{answerSubmitting=false}}
async function processAttempts(){if(processing||!host||!roomData?.attempts||roomData.game?.phase!=='quiz')return;processing=true;try{let g=roomData.game;let attempts=Object.entries(roomData.attempts).filter(([id,v])=>v.turnId===g.turnId&&v.team===g.team&&Number(roomData.members?.[id]?.team)===g.team).sort((a,b)=>(a[1].submittedAt||0)-(b[1].submittedAt||0));if(!attempts.length)return;let [who,a]=attempts[0],id=g.questionId,q=roomData.questions?.[id]||DEFAULT_QUESTIONS[id];const winning=attempts.find(([_,v])=>v.passed!==true&&v.choice===q.answer);if(!winning&&attempts.length<roster(roomData,g.team).length)return;const correct=!!winning,chosen=winning?.[1]||a;const priorOwner=Number(g.owners?.[id]??-1);let msg=correct?`✅ ${chosen.nickname} 정답! ${names[g.team]} 팀이 ${q.name||DEFAULT_QUESTIONS[id].name} 거점을 확보했습니다. ${q.explain}`:`❌ 모두 오답 또는 패스! 정답: ${q.options[q.answer]}. ${q.explain}`;let result=await runTransaction(ref(db,'rooms/'+room+'/game'),old=>{if(!old||old.phase!=='quiz'||old.turnId!==g.turnId)return;const owners=[...old.owners],decorationVersions={...(old.decorationVersions||{})};if(correct){owners[id]=old.team;if(Number(old.owners[id])!==Number(old.team))decorationVersions[id]=Number(decorationVersions[id]||0)+1}const skipTurns={...(old.skipTurns||{})};if(!correct)skipTurns[old.team]=Number(skipTurns[old.team]||0)+1;return {...old,owners,decorationVersions,skipTurns,bonusRoll:correct?old.bonusRoll:false,phase:'next',message:msg+(correct?'':' 거점 획득 실패 · 다음 자기 차례 1회 쉬기.')}},{applyLocally:false});if(result.committed){if(correct&&priorOwner!==g.team)await remove(ref(db,'rooms/'+room+'/landmarks/'+id)).catch(()=>{});await remove(ref(db,'rooms/'+room+'/attempts'));}}finally{processing=false}}
$('submit').onclick=async()=>{if(!roomData)return;let id=+$('topic').value,opts=$('opts').value.split('\n').map(s=>s.trim()).filter(Boolean),q=$('q').value.trim(),explain=$('explain').value.trim();if(!Number.isInteger(id)||id<0||id>=24)return alert('올바른 거점을 선택하세요.');if(!q||opts.length!==4||!explain)return alert('문제, 보기 4개, 해설을 모두 입력하세요.');if(q.length>200||opts.some(s=>s.length>100)||explain.length>300)return alert('문제 또는 보기가 너무 깁니다.');const g=roomData.game,claim=roomData.pendingClaims?.[id],isClaim=!!claim&&Number(claim.team)===Number(roomData.members?.[uid]?.team);if(!isClaim)return alert('우리 팀의 출제 대기 거점을 선택해 주세요.');if(g.phase==='finished')return alert('게임이 종료되었습니다.');try{await set(ref(db,'rooms/'+room+'/completedQuestions/'+id),{authorUid:uid,author:roomData.members?.[uid]?.nickname||'참가자',topic:id,q,options:opts,answer:+$('answer').value-1,explain,claimTurnId:claim.turnId,claimTeam:claim.team,createdAt:Date.now()});$('q').value='';$('opts').value='';$('explain').value='';notify('✅ 출제 완료! 자동 승인 및 점령을 처리하고 있습니다.')}catch(e){alert('출제 완료 오류: '+e.message)}};
$('landmarkSubmit').onclick=async()=>{if(!roomData||roomData.game?.phase==='finished')return alert('게임이 종료되어 거점을 꾸밀 수 없습니다.');const topic=+$('landmarkTopic').value,name=$('landmarkName').value.trim();let imageUrl=$('landmarkImage').value.trim();const photo=$('landmarkFile').files?.[0];if(photo){try{imageUrl=await compressPhoto(photo)}catch(e){return alert(e.message)}}const myTeam=Number(roomData.members?.[uid]?.team??-1);if(!host&&Number(roomData.game?.owners?.[topic]??-1)!==myTeam)return alert('우리 팀이 점령한 거점만 꾸밀 수 있습니다.');if(!Number.isInteger(topic)||topic<0||topic>=24||Number(roomData.game?.owners?.[topic]??-1)<0)return alert('먼저 점령한 거점을 선택하세요.');if(!name||name.length>24)return alert('거점 이름을 1~24자로 입력하세요.');if(imageUrl&&!safeImage(imageUrl))return alert('사진 파일 또는 https:// 이미지 주소를 확인하세요.');try{await push(ref(db,'rooms/'+room+'/landmarkProposals'),{authorUid:uid,author:roomData.members?.[uid]?.nickname||'참가자',topic,name,imageUrl,ownerTeam:Number(roomData.game.owners[topic]),territoryVersion:Number(roomData.game.decorationVersions?.[topic]||0),createdAt:Date.now()});$('landmarkName').value='';$('landmarkImage').value='';$('landmarkFile').value='';notify('🎨 꾸미기 적용 중입니다. 이름·사진과 보너스 +1점이 자동 반영됩니다.')}catch(e){alert('제출 오류: '+e.message)}};
let completedProcessing=false;async function processCompletedQuestions(){if(completedProcessing||!host||!roomData?.completedQuestions)return;completedProcessing=true;try{for(const [id,p] of Object.entries(roomData.completedQuestions||{})){const c=roomData.pendingClaims?.[id];if(!c||Number(c.team)!==Number(p.claimTeam)||Number(c.turnId)!==Number(p.claimTurnId)){await remove(ref(db,'rooms/'+room+'/completedQuestions/'+id));continue}if(!p.q||!Array.isArray(p.options)||p.options.length!==4||!p.explain||!Number.isInteger(p.answer)||p.answer<0||p.answer>3){await remove(ref(db,'rooms/'+room+'/completedQuestions/'+id));continue}
// Publish the complete question before enabling answers; never show the default question while waiting.
await set(ref(db,'rooms/'+room+'/questions/'+id),{q:p.q,options:p.options,answer:p.answer,explain:p.explain,name:'거점 '+(Number(id)+1)});
const result=await runTransaction(ref(db,'rooms/'+room+'/game'),g=>{if(!g||g.phase==='finished'||Number(g.owners?.[id])!==-1)return;const owners=[...g.owners];owners[Number(id)]=Number(p.claimTeam);const waiting=g.phase==='wait'&&Number(g.questionId)===Number(id),own=Number(g.team)===Number(p.claimTeam),authorDone=g.phase==='author'&&Number(g.questionId)===Number(id);return {...g,owners,phase:waiting?(own?'next':'quiz'):authorDone?'next':g.phase,message:waiting?(own?'✅ 우리 팀의 출제가 완료되어 거점을 확보했습니다.':'❓ 출제 완료! '+names[g.team]+' 팀은 방금 완성된 문제를 풀어 거점 점령에 도전하세요.'):'✅ '+names[p.claimTeam]+' 팀이 거점 '+(Number(id)+1)+' 문제를 완성해 자동 점령했습니다.'}},{applyLocally:false});if(result.committed)await remove(ref(db,'rooms/'+room+'/pendingClaims/'+id));await remove(ref(db,'rooms/'+room+'/completedQuestions/'+id))}}finally{completedProcessing=false}}
let landmarkProcessing=false;
async function processLandmarkProposals(){if(landmarkProcessing||!host||!roomData?.landmarkProposals)return;landmarkProcessing=true;const handled=new Set();let failed=false;try{for(const [key,p] of Object.entries(roomData.landmarkProposals||{})){const d=roomData,g=d.game,topic=Number(p.topic),team=Number(p.ownerTeam??d.members?.[p.authorUid]?.team??-1),version=Number(p.territoryVersion||0),image=safeImage(p.imageUrl||'');const valid=g.phase!=='finished'&&Number.isInteger(topic)&&topic>=0&&topic<24&&team>=0&&team<4&&Number(g.owners?.[topic])===team&&version===Number(g.decorationVersions?.[topic]||0)&&(p.authorUid===d.hostUid||Number(d.members?.[p.authorUid]?.team)===team)&&typeof p.name==='string'&&p.name.trim().length>0&&p.name.length<=24&&(!p.imageUrl||!!image);if(valid){await set(ref(db,'rooms/'+room+'/landmarks/'+topic),{name:p.name.trim(),imageUrl:image,ownerTeam:team,version});}await remove(ref(db,'rooms/'+room+'/landmarkProposals/'+key));handled.add(key);}}catch(e){failed=true;throw e}finally{landmarkProcessing=false;if(!failed&&Object.keys(roomData?.landmarkProposals||{}).some(key=>!handled.has(key)))setTimeout(()=>processLandmarkProposals().catch(e=>notify(e.message)),100)}}
function drawPending(){let entries=Object.entries(roomData?.proposals||{});$('pending').innerHTML=entries.length?'':'<p class="muted">검토할 문제가 없습니다.</p>';for(let [key,p] of entries){let article=document.createElement('article');article.innerHTML='<b>'+clean(DEFAULT_QUESTIONS[p.topic]?.name)+' · '+clean(p.author)+'</b><p>'+clean(p.q)+'</p><p class="muted">'+(p.options||[]).map((x,i)=>(i+1)+'. '+clean(x)).join(' / ')+'</p><p class="muted">정답: '+(p.answer+1)+' · '+clean(p.explain)+'</p>';let yes=document.createElement('button');yes.className='primary';yes.textContent='승인';yes.onclick=async()=>{await update(ref(db,'rooms/'+room+'/questions/'+p.topic),{q:p.q,options:p.options,answer:p.answer,explain:p.explain,name:p.q.slice(0,18)});if(p.claimTurnId>=0&&roomData.pendingClaims?.[p.topic]?.turnId===p.claimTurnId&&Number(roomData.pendingClaims?.[p.topic]?.team)===Number(p.claimTeam)){const claimResult=await runTransaction(ref(db,'rooms/'+room+'/game'),g=>{if(!g||g.phase==='finished'||Number(g.owners[p.topic])!==-1)return;const owners=[...g.owners];owners[p.topic]=p.claimTeam;return {...g,owners,message:names[p.claimTeam]+' 팀이 거점 '+(p.topic+1)+' 문제를 출제하여 점령했습니다.'}},{applyLocally:false});if(claimResult.committed)await remove(ref(db,'rooms/'+room+'/pendingClaims/'+p.topic))}await remove(ref(db,'rooms/'+room+'/proposals/'+key))};let no=document.createElement('button');no.textContent='반려';no.onclick=()=>remove(ref(db,'rooms/'+room+'/proposals/'+key));article.append(yes,no);$('pending').appendChild(article)}
const dest=$('landmarkPending'),entries2=Object.values(roomData?.landmarkProposals||{});dest.innerHTML=entries2.length?'<p class="muted">🎨 '+entries2.length+'건의 꾸미기를 자동 반영 중입니다.</p>':'<p class="muted">꾸미기는 적용 즉시 게임판과 점수에 자동 반영됩니다.</p>';}
DEFAULT_QUESTIONS.forEach((x,i)=>{for(const id of ['topic','landmarkTopic']){let op=document.createElement('option');op.value=i;op.textContent='거점 '+(i+1);$(id).appendChild(op)}});
$('team').onchange=()=>{$('topic').value=String(+$('team').value)};
try{if(firebaseConfig.apiKey.startsWith('PASTE_'))throw Error('firebase-config.js에 Firebase 설정을 입력해 주세요.');const app=initializeApp(firebaseConfig);auth=getAuth(app);db=getDatabase(app);await signInAnonymously(auth);uid=auth.currentUser.uid;notify('🟢 Firebase 연결 완료 · 방을 만들거나 입장하세요.');let invited=new URLSearchParams(location.search).get('room');if(invited&&/^[A-Z0-9]{6}$/i.test(invited)){$('roomCode').value=invited.toUpperCase();sessionStorage.removeItem('historyRoom');sessionStorage.removeItem('historyHost');}let saved=invited?null:sessionStorage.getItem('historyRoom');if(saved){$('roomCode').value=saved;let isHost=sessionStorage.getItem('historyHost')==='1';try{await enter(saved,isHost)}catch(e){notify('이전 방 재입장 실패: '+e.message)}}}catch(e){notify('⚠️ '+e.message)}
